"""Half-open integer interval utilities."""


def _clean(intervals):
    """Return only the non-empty intervals as (start, end) tuples."""
    return [(s, e) for (s, e) in intervals if s < e]


def merge(intervals):
    """Merge overlapping and touching half-open intervals.

    Returns a list of (start, end) tuples sorted by start.
    """
    cleaned = sorted(_clean(intervals))
    if not cleaned:
        return []
    out = [list(cleaned[0])]
    for s, e in cleaned[1:]:
        if s <= out[-1][1]:
            if e > out[-1][1]:
                out[-1][1] = e
        else:
            out.append([s, e])
    return [(s, e) for s, e in out]


def free_gaps(intervals, window):
    """Return the maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    clipped = [
        (max(s, ws), min(e, we))
        for (s, e) in _clean(intervals)
        if s < we and e > ws
    ]
    merged = merge(clipped)
    gaps = []
    cur = ws
    for s, e in merged:
        if s > cur:
            gaps.append((cur, s))
        if e > cur:
            cur = e
        if cur >= we:
            break
    if cur < we:
        gaps.append((cur, we))
    return gaps


def max_overlap(intervals):
    """Return the largest number of non-empty intervals covering one common point."""
    events = []
    for s, e in _clean(intervals):
        events.append((s, 1))
        events.append((e, -1))
    if not events:
        return 0
    # Sort by coordinate; at equal coordinates, ends (-1) before starts (+1)
    # so half-open intervals sharing only a boundary do not overlap.
    events.sort(key=lambda ev: (ev[0], ev[1]))
    best = cur = 0
    for _, delta in events:
        cur += delta
        if cur > best:
            best = cur
    return best

"""LRU cache with per-entry time-to-live."""

import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = int(capacity)
        self._clock = clock
        # key -> (value, expires); expires is None or an absolute timestamp.
        # OrderedDict order is recency: first = LRU, last = MRU.
        self._store = OrderedDict()

    # ------------------------------------------------------------------
    def _is_live(self, expires):
        if expires is None:
            return True
        return self._clock() < expires

    def _purge_expired(self):
        now = self._clock()
        dead = [
            key
            for key, (_value, expires) in self._store.items()
            if expires is not None and now >= expires
        ]
        for key in dead:
            del self._store[key]
        return len(dead)

    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        now = self._clock()
        expires = None if ttl is None else now + ttl
        if key in self._store:
            # Replace value, restart lifetime, mark most recently used.
            self._store[key] = (value, expires)
            self._store.move_to_end(key)
        else:
            if len(self._store) >= self._capacity:
                self._purge_expired()
            if len(self._store) >= self._capacity:
                # Still full: evict least recently used live entry.
                self._store.popitem(last=False)
            self._store[key] = (value, expires)

    def get(self, key, default=None):
        entry = self._store.get(key)
        if entry is None:
            return default
        value, expires = entry
        if not self._is_live(expires):
            del self._store[key]
            return default
        self._store.move_to_end(key)
        return value

    def evict_expired(self):
        return self._purge_expired()

    # ------------------------------------------------------------------
    def __contains__(self, key):
        entry = self._store.get(key)
        if entry is None:
            return False
        # Must not change recency.
        return self._is_live(entry[1])

    def __len__(self):
        return sum(1 for _key, expires in self._store.values() if self._is_live(expires))

    def keys(self):
        return [key for key, (_value, expires) in self._store.items() if self._is_live(expires)]

